     "ex": "from typing import Protocol\n\nclass Notifier(Protocol):\n    def send(self, text: str) -> bool: ...\n\nclass FakeNotifier:\n    def __init__(self):\n        self.sent: list[str] = []\n    def send(self, text: str) -> bool:\n        self.sent.append(text)\n        return True\n\ndef alert(n: Notifier, msg: str) -> None:\n    n.send(f\"[ALERT] {msg}\")\n\nfake = FakeNotifier()\nalert(fake, \"queue backlog 120\")\nprint(fake.sent)",
